import React from 'react';

// Just enough markdown for assistant messages: bold, inline code, bullet
// lists and paragraphs. The messages are generated by our own narration
// helpers and prompts, so the dialect is known and small.

function inline(text, keyPrefix) {
  const parts = [];
  const pattern = /(\*\*[^*]+\*\*|`[^`]+`)/g;
  let last = 0;
  let match;
  let i = 0;

  while ((match = pattern.exec(text)) !== null) {
    if (match.index > last) parts.push(text.slice(last, match.index));
    const token = match[0];
    if (token.startsWith('**')) {
      parts.push(<strong key={`${keyPrefix}-b${i}`}>{token.slice(2, -2)}</strong>);
    } else {
      parts.push(<code key={`${keyPrefix}-c${i}`}>{token.slice(1, -1)}</code>);
    }
    last = match.index + token.length;
    i += 1;
  }
  if (last < text.length) parts.push(text.slice(last));
  return parts;
}

export default function Markdown({ text }) {
  const lines = String(text || '').split('\n');
  const blocks = [];
  let paragraph = [];
  let list = [];

  const flushParagraph = () => {
    if (!paragraph.length) return;
    blocks.push(
      <p key={`p${blocks.length}`}>{inline(paragraph.join(' '), `p${blocks.length}`)}</p>
    );
    paragraph = [];
  };
  const flushList = () => {
    if (!list.length) return;
    const items = list;
    blocks.push(
      <ul key={`u${blocks.length}`}>
        {items.map((item, i) => (
          <li key={i}>{inline(item, `u${blocks.length}-${i}`)}</li>
        ))}
      </ul>
    );
    list = [];
  };

  lines.forEach((raw) => {
    const line = raw.trimEnd();
    if (!line.trim()) {
      flushParagraph();
      flushList();
      return;
    }
    const bullet = line.match(/^\s*[-*]\s+(.*)$/);
    if (bullet) {
      flushParagraph();
      list.push(bullet[1]);
      return;
    }
    flushList();
    paragraph.push(line.trim());
  });
  flushParagraph();
  flushList();

  return <>{blocks}</>;
}
